package com.example.lokihealbe;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.widget.*;import android.text.InputType;import android.view.WindowManager;
public final class MainActivity extends Activity {
 private TextView status;private EditText email,password;private boolean linking;private volatile String devicePin="";
 protected void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);LinearLayout box=new LinearLayout(this);box.setOrientation(1);int pad=(int)(20*getResources().getDisplayMetrics().density);box.setPadding(pad,pad,pad,pad);box.setImportantForAutofill(8);ScrollView scroll=new ScrollView(this);scroll.addView(box);setContentView(scroll);
  TextView intro=new TextView(this);intro.setText("ロキ HEALBE直接連携（検証版）\n\n公式SDKで、HEALBEのサーバーにあるエネルギー収支の取得を試します。公式アプリを開かず取得できるかはログイン後に確認します。\n\nログイン情報はHEALBEへ送信し、この入力欄のパスワードを保存・ログ出力しません。PC・チャットには入力しないでください。端末内に保存する収支は暗号化し、ロキだけが読み取れます。本体への接続は、検索結果から選択し確認した場合に試します。公式アプリとの接続に影響する場合があります。");box.addView(intro);
  email=new EditText(this);email.setHint("HEALBEのメールアドレス");email.setInputType(33);email.setSaveEnabled(false);box.addView(email);password=new EditText(this);password.setHint("HEALBEのパスワード");password.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);password.setSaveEnabled(false);box.addView(password);
  EditText pinInput=new EditText(this);pinInput.setHint("GoBeの現在のPIN（本体接続時のみ）");pinInput.setInputType(18);pinInput.setSaveEnabled(false);pinInput.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){devicePin=s.toString();}public void afterTextChanged(android.text.Editable e){}});box.addView(pinInput);
  button(box,"ログインして取得を試す",()->{if(linking||!permissions())return;String user=email.getText().toString().trim(),secret=password.getText().toString();if(user.isEmpty()||secret.isEmpty()){status.setText("メールアドレスとパスワードを入力してください");return;}password.setText("");linking=true;status.setText("ログイン中");new Thread(()->{try{if(CloudSync.login(this,user,secret)){SyncJob.schedule(this);CloudSync.refresh(this);}else CloudSync.state(this,"HEALBEアプリでアカウントの設定を確認してください");}catch(Exception error){CloudSync.state(this,"ログインできませんでした。入力情報と通信をご確認ください");}runOnUiThread(()->{linking=false;showStatus();});},"HEALBE-login").start();});
  button(box,"今すぐ同期を確認",()->{if(!permissions())return;status.setText("同期を確認中");new Thread(()->{CloudSync.refresh(this);runOnUiThread(this::showStatus);},"HEALBE-manual-sync").start();});
  button(box,"連携を停止・収支を消す",()->{CloudSync.stop(this);getSystemService(android.app.job.JobScheduler.class).cancel(694);SnapshotStore.clear(this);new Thread(()->{try{com.healbe.healbesdk.business_api.HealbeSdk.get().USER.logout().timeout(10,java.util.concurrent.TimeUnit.SECONDS).blockingAwait();}catch(Exception ignored){}CloudSync.state(this,"連携を停止しました");runOnUiThread(this::showStatus);}).start();});
  button(box,"GoBe本体を選んで接続を試す",()->{if(linking||!permissions())return;status.setText("近くのGoBeを検索中（15秒）");new Thread(()->{try{CloudSync.init(this);if(!com.healbe.healbesdk.business_api.user.data.HealbeSessionState.isUserValid(com.healbe.healbesdk.business_api.HealbeSdk.get().USER.prepareSession().timeout(15,java.util.concurrent.TimeUnit.SECONDS).blockingGet())){runOnUiThread(()->status.setText("再ログインが必要です"));return;}java.util.List<com.healbe.healbesdk.business_api.user_storage.entity.HealbeDevice> devices=com.healbe.healbesdk.business_api.HealbeSdk.get().GOBE.scan().distinct(v->v.getMac()).take(15,java.util.concurrent.TimeUnit.SECONDS).toList().blockingGet();getSharedPreferences("link",0).edit().putInt("scanCount",devices.size()).putString("scanResult","completed").apply();runOnUiThread(()->{if(isFinishing()||isDestroyed())return;if(devices.isEmpty()){status.setText("GoBeが見つかりません。本体を近づけて再度お試しください");return;}String[] labels=new String[devices.size()];for(int i=0;i<labels.length;i++)labels[i]=devices.get(i).getName()+" / "+devices.get(i).getMac();new AlertDialog.Builder(this).setTitle("自分のGoBeを選択").setItems(labels,(d,index)->new AlertDialog.Builder(this).setMessage("公式HEALBEアプリとの接続に影響する可能性があります。このGoBeへの接続を試しますか？").setNegativeButton("戻る",null).setPositiveButton("接続を試す",(a,b1)->new Thread(()->{try{com.healbe.healbesdk.business_api.HealbeSdk sdk=com.healbe.healbesdk.business_api.HealbeSdk.get();sdk.GOBE.set(devices.get(index)).timeout(10,java.util.concurrent.TimeUnit.SECONDS).blockingAwait();sdk.GOBE.connect().andThen(sdk.GOBE.observeConnectionState().concatMapSingle(v->{if(v==com.healbe.healbesdk.device_api.ClientState.REQUEST_PIN_CODE&&!devicePin.isEmpty())return sdk.GOBE.setPin(devicePin).toSingleDefault(v);return io.reactivex.Single.just(v);}).doOnNext(v->getSharedPreferences("link",0).edit().putString("connectionState",v.name()).apply())).filter(v->v==com.healbe.healbesdk.device_api.ClientState.READY).firstOrError().timeout(45,java.util.concurrent.TimeUnit.SECONDS).blockingGet();CloudSync.refresh(this);}catch(Exception e){String phase=getSharedPreferences("link",0).getString("connectionState","UNKNOWN");CloudSync.state(this,"本体接続を完了できませんでした（"+phase+"）。公式アプリの接続状態やPIN認証を確認してください");}runOnUiThread(this::showStatus);},"HEALBE-device-connect").start()).show()).setNegativeButton("閉じる",null).show();});}catch(Exception e){Throwable cause=e;for(int k=0;k<8&&cause.getCause()!=null;k++)cause=cause.getCause();getSharedPreferences("link",0).edit().putString("scanResult","failed").putString("scanErrorType",cause.getClass().getSimpleName()).apply();runOnUiThread(()->status.setText("GoBe検索を開始できませんでした。Bluetoothと許可を確認してください"));}},"HEALBE-device-scan").start();});
  status=new TextView(this);box.addView(status);showStatus();if(getSharedPreferences("link",0).getBoolean("linked",false))SyncJob.schedule(this);
 }
 private boolean permissions(){if(Build.VERSION.SDK_INT>=31&&(checkSelfPermission("android.permission.BLUETOOTH_CONNECT")!=PackageManager.PERMISSION_GRANTED||checkSelfPermission("android.permission.BLUETOOTH_SCAN")!=PackageManager.PERMISSION_GRANTED)){new AlertDialog.Builder(this).setMessage("公式SDKの初期化に必要な「付近のデバイス」の許可をお願いします。ロキからGoBeの接続先を切り替える操作は行いません。").setPositiveButton("許可設定へ",(d,w)->requestPermissions(new String[]{"android.permission.BLUETOOTH_CONNECT","android.permission.BLUETOOTH_SCAN"},1)).setNegativeButton("戻る",null).show();return false;}return true;}
 private void button(LinearLayout box,String title,Runnable action){Button b=new Button(this);b.setText(title);b.setOnClickListener(v->action.run());box.addView(b);}
 private void showStatus(){if(isFinishing()||isDestroyed())return;status.setText(getSharedPreferences("link",0).getString("status","未ログインです。バックグラウンド取得はまだ確認できていません。"));}
}
